import pytest
from datetime import date
from mymod import LateFeeCalculator

def mk(today): return LateFeeCalculator(today=today)

def test_zero_balance():
    assert mk(date(2026,1,30)).compute_fee_cents(0, date(2026,1,1)) == 0

def test_negative_balance():
    assert mk(date(2026,1,30)).compute_fee_cents(-100, date(2026,1,1)) == 0

def test_default_today():
    assert LateFeeCalculator()._today == date.today()

def test_within_grace():
    assert mk(date(2026,1,12)).compute_fee_cents(10000, date(2026,1,1)) == 0

def test_end_before_start():
    assert mk(date(2026,1,1)).compute_fee_cents(10000, date(2026,2,1)) == 0

def test_min_fee():
    assert mk(date(2026,1,26)).compute_fee_cents(10000, date(2026,1,1)) == 500

def test_max_cap():
    assert mk(date(2027,1,1)).compute_fee_cents(10000, date(2026,1,1)) == 2500

def test_weekend_skip():
    f = mk(date(2026,1,5)).compute_fee_cents(100000, date(2026,1,3))
    assert f == 0

def test_prorated():
    r = mk(date(2026,3,1)).compute_fee_cents(100000, date(2026,1,1))
    assert 500 < r <= 25000
